from pathlib import Path
import json

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {"pass": False, "score": 0.0, "feedback": "external_services_path is None; cannot check mailbox.json"}

    mailbox_path = Path(external_services_path) / "mailbox.json"
    if not mailbox_path.exists():
        return {"pass": False, "score": 0.0, "feedback": "mailbox.json not found"}

    with open(mailbox_path, "r") as f:
        data = json.load(f)

    emails = data.get("emails", [])

    # Find email with id 38
    target_email = None
    for email in emails:
        if str(email.get("email_id", "")) == "38":
            target_email = email
            break

    if target_email is None:
        return {"pass": False, "score": 0.0, "feedback": "Email with id 38 not found in mailbox.json"}

    folder = target_email.get("folder", "")
    if folder.upper() == "INBOX":
        return {"pass": True, "score": 1.0, "feedback": f"Email id 38 is in INBOX folder as required."}
    else:
        return {"pass": False, "score": 0.0, "feedback": f"Email id 38 is in folder '{folder}', expected INBOX."}

