    except Exception as e:
        return {"pass": False, "score": 0.0, "feedback": f"Error reading {tracker_path.name}: {e}"}

from pathlib import Path
import openpyxl

def verify(workspace_path, external_services_path=None):
    # Search for any leave tracker xlsx file with loose matching
    ws_path = Path(workspace_path)
    tracker_files = set()
    for pattern in ["*leave_tracker*", "*Leave_Tracker*", "*leave*tracker*", "*Leave*Tracker*", "*LEAVE*TRACKER*"]:
        tracker_files.update(ws_path.glob(pattern))
    xlsx_files = [f for f in tracker_files if f.suffix.lower() == ".xlsx"]

    if not xlsx_files:
        # Broaden: any xlsx with 'leave' or 'tracker' in name
        all_xlsx = list(ws_path.glob("*.xlsx"))
        if not all_xlsx:
            # Try recursively
            all_xlsx = list(ws_path.rglob("*.xlsx"))
        if not all_xlsx:
            return {"pass": False, "score": 0.0, "feedback": "No .xlsx file found in workspace."}
        leave_files = [f for f in all_xlsx if "leave" in f.name.lower() or "tracker" in f.name.lower()]
        if leave_files:
            xlsx_files = leave_files
        else:
            xlsx_files = all_xlsx

    # Try each candidate file
    for tracker_path in xlsx_files:
        try:
            wb = openpyxl.load_workbook(tracker_path, data_only=True)
            # Try active sheet first, then all sheets
            sheets_to_check = [wb.active] + [wb[s] for s in wb.sheetnames if wb[s] != wb.active]
            for ws in sheets_to_check:
                # Check N11 (row=11, column=14)
                cell_value = ws.cell(row=11, column=14).value
                if cell_value is not None:
                    cell_str = str(cell_value).strip().lower()
                    if "p1" in cell_str:
                        return {"pass": True, "score": 1.0, "feedback": f"Cell N11 in '{tracker_path.name}' (sheet '{ws.title}') contains '{cell_value}' which includes 'P1'."}

            # Also search for LC-2026-0321 row and check its priority column
            for ws in sheets_to_check:
                target_row = None
                priority_col = None
                # Find header row and priority column
                for row in range(1, min(ws.max_row + 1, 5)):
                    for col in range(1, ws.max_column + 1):
                        val = ws.cell(row=row, column=col).value
                        if val and "priority" in str(val).strip().lower():
                            priority_col = col
                            break
                    if priority_col:
                        break
                # Find row with LC-2026-0321
                for row in range(1, ws.max_row + 1):
                    for col in range(1, ws.max_column + 1):
                        val = ws.cell(row=row, column=col).value
                        if val and "lc-2026-0321" in str(val).strip().lower():
                            target_row = row
                            break
                    if target_row:
                        break
                if target_row and priority_col:
                    pval = ws.cell(row=target_row, column=priority_col).value
                    if pval and "p1" in str(pval).strip().lower():
                        return {"pass": True, "score": 1.0, "feedback": f"Row {target_row} for LC-2026-0321 in '{tracker_path.name}' (sheet '{ws.title}') has priority '{pval}' which includes 'P1'."}
            wb.close()
        except Exception as e:
            continue

    # Final failure - try to give useful info
    try:
        tracker_path = xlsx_files[0]
        wb = openpyxl.load_workbook(tracker_path, data_only=True)
        ws = wb.active
        cell_value = ws.cell(row=11, column=14).value
        wb.close()
        return {"pass": False, "score": 0.0, "feedback": f"Cell N11 in '{tracker_path.name}' contains '{cell_value}', expected a value containing 'P1' (case-insensitive). Checked {len(xlsx_files)} file(s)."}
    except Exception as e:
        return {"pass": False, "score": 0.0, "feedback": f"Could not verify. Error: {e}. Checked files: {[f.name for f in xlsx_files]}"}

from pathlib import Path
import json

def verify(workspace_path, external_services_path=None):
    mailbox_path = None

    # Try external_services_path first, then workspace_path
    if external_services_path:
        candidate = Path(external_services_path) / "mailbox.json"
        if candidate.exists():
            mailbox_path = candidate

    if not mailbox_path:
        candidate = Path(workspace_path) / "mailbox.json"
        if candidate.exists():
            mailbox_path = candidate

    if not mailbox_path:
        return {"pass": False, "score": 0.0, "feedback": "No mailbox.json found in either external_services_path or workspace_path."}

    try:
        with open(mailbox_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception as e:
        return {"pass": False, "score": 0.0, "feedback": f"Failed to read/parse mailbox.json: {e}"}

    emails = data.get("emails", [])
    total_emails = len(emails)
    issues = []
    score = 1.0

    # Build a lookup by email_id (could be int or string)
    emails_by_id = {}
    max_email_id = None
    for email in emails:
        eid = email.get("email_id", email.get("id", None))
        if eid is not None:
            try:
                eid_int = int(eid)
            except (ValueError, TypeError):
                eid_int = None
            if eid_int is not None:
                emails_by_id[eid_int] = email
                if max_email_id is None or eid_int > max_email_id:
                    max_email_id = eid_int

    # Check: no emails after email_id 40
    emails_after_40 = [eid for eid in emails_by_id if eid > 40]
    if emails_after_40:
        issues.append(f"Found emails with email_id > 40: {sorted(emails_after_40)}. There should be no emails after email_id 40.")
        score = 0.0

    # Check: email_id 40 exists and is addressed to tomas.guerrero@ridgelinegear.com
    expected_recipient = "tomas.guerrero@ridgelinegear.com"
    if 40 in emails_by_id:
        email_40 = emails_by_id[40]
        to_addr = email_40.get("to_addr", email_40.get("to", ""))
        # Normalize: accept string or list
        if isinstance(to_addr, str):
            to_addrs = [to_addr.strip().lower()]
        elif isinstance(to_addr, list):
            to_addrs = [a.strip().lower() for a in to_addr]
        else:
            to_addrs = []

        if expected_recipient not in to_addrs:
            issues.append(f"Email with email_id 40 is addressed to '{to_addr}', expected '{expected_recipient}'.")
            score = 0.0
    else:
        issues.append(f"No email with email_id 40 found. Available email_ids: {sorted(emails_by_id.keys())[-10:] if emails_by_id else 'none'}")
        score = 0.0

    if issues:
        return {"pass": False, "score": score, "feedback": "Issues found: " + "; ".join(issues)}
    else:
        email_40 = emails_by_id[40]
        to_addr = email_40.get("to_addr", email_40.get("to", ""))
        return {"pass": True, "score": 1.0, "feedback": f"mailbox.json has no emails after email_id 40 (max email_id is {max_email_id}). Email_id 40 is addressed to '{to_addr}', which matches the expected recipient '{expected_recipient}'."}

